<?php
define('EIPSI_STUDY_ENGINE_KEYRING',array('current'=>'HTTP_TEST','keys'=>array('HTTP_TEST'=>str_repeat('6b',32))));
define('EIPSI_STUDY_ENGINE_ACCESS_KEYRING',array('current'=>'ACCESS_TEST','keys'=>array('ACCESS_TEST'=>str_repeat('61',32))));
require __DIR__.'/m0/bootstrap.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Owner.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/AnalyticalExport.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/longitudinal.php';require __DIR__.'/study-engine/cross-sectional/support.php';require __DIR__.'/study-engine/persistence/support.php';require __DIR__.'/study-engine/longitudinal/support.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/runtime/NativeBridge.php';
use EIPSI\AssessmentEditor\Definition as D;
use EIPSI\AssessmentEditor\Answers;
use EIPSI\AssessmentEditor\Runtime\Owner;
use EIPSI\StudyEngine\Longitudinal as L;
$tests=0;$failures=0;$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z');
function rgtest($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.get_class($e).' '.$e->getMessage()."\n";}}
function rgassert($v){if(!$v)throw new RuntimeException('Registration assertion failed');}
function rgdef($lang='en'){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']='AE_REG_'.bin2hex(random_bytes(6));$d['content_language']=$lang;$d['elements']=array(array('id'=>'EL_REG','type'=>'registration','response_key'=>'R_REG','properties'=>array('label'=>'Registration','helper'=>'','required'=>true),'options'=>array(),'children'=>array()));$d['flow']['pages']=array();return D::validate($d);}
function rgmeta($d){return array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$d['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);}
function rgcmd($f,$action,$answers=array()){return array('action'=>$action,'command_id'=>'NC_'.bin2hex(random_bytes(8)),'revision'=>$f['revision'],'version_id'=>$f['version_id'],'csrf'=>$f['csrf'],'answers'=>$answers,'touched'=>array(),'metadata'=>$f['metadata']??rgmeta($f['definition']));}
$owner=new Owner();$d=rgdef();
rgtest('bilingual editable definition and question JSON roundtrip',function(){foreach(array('en'=>'Register','es'=>'Registrar') as $lang=>$label){$d=rgdef($lang);rgassert($d['elements'][0]['properties']['register_label']===$label);$d['elements'][0]['properties']['register_label']='Custom';rgassert(D::validate(json_decode(D::json($d),true))['elements'][0]['properties']['register_label']==='Custom');}});
rgtest('server validates both choices and rejects hidden data or malformed objects',function()use($d){$e=$d['elements'][0];rgassert(Answers::errors($d,array()));$optional=$d;$optional['elements'][0]['properties']['required']=false;foreach(array('',array(),false)as$value)rgassert(Answers::errors($optional,array('R_REG'=>$value)));foreach(array(array('register'=>false,'value'=>null),array('register'=>true,'value'=>'edited@example.test')) as $value)rgassert(!Answers::errors($d,array('R_REG'=>$value)));foreach(array(array('register'=>false,'value'=>'hidden'),array('register'=>true,'value'=>''),array('register'=>'yes','value'=>'x'),array('register'=>true,'value'=>'x','extra'=>true),array('register'=>true,'value'=>str_repeat('x',2001))) as $value)rgassert(Answers::errors($d,array('R_REG'=>$value)));});
rgtest('analytical exports preserve choice and value for manual and JSON consumers',function()use($d){foreach(array(array('register'=>true,'value'=>'edited@example.test'),array('register'=>false,'value'=>null)) as $value){$rows=EIPSI\AssessmentEditor\AnalyticalExport::rows($d,array('R_REG'=>$value));rgassert($rows[0]['value']===$value);rgassert($rows[0]['selected_option_id']===($value['register']?'register':'decline'));rgassert(strpos(EIPSI\AssessmentEditor\AnalyticalExport::csv($rows),'register')!==false);rgassert(json_decode(json_encode($rows),true)[0]['value']===$value);}});
rgtest('metadata accepts only a boolean registration state',function()use($d){$m=rgmeta($d);$m['events']=array(array('timestamp'=>1,'kind'=>'interaction','identity'=>'EL_REG','state'=>true));$d['flow']['metadata_profile']='detailed';EIPSI\AssessmentEditor\Runtime\Metadata::validate($m,$d,'NV_TEST');$m['events'][0]['state']=array('register'=>true,'value'=>'private@example.test');$rejected=false;try{EIPSI\AssessmentEditor\Runtime\Metadata::validate($m,$d,'NV_TEST');}catch(Throwable $e){$rejected=true;}rgassert($rejected);});
rgtest('standalone Native persists partial, restored edits and final choice',function()use($owner,$d){EIPSI\AssessmentEditor\Repository::save($d,0);$v=$owner->publish($d['id'],1);$f=$owner->view($owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1))['execution_id']);rgassert($f['registration_source']===$f['execution_id']);$f=$owner->command($f['execution_id'],rgcmd($f,'open'));$answer=array('R_REG'=>array('register'=>true,'value'=>'custom record'));$f=$owner->command($f['execution_id'],rgcmd($f,'partial',$answer));$f=$owner->view($f['execution_id']);rgassert($f['session']['answers']===$answer);$f=$owner->command($f['execution_id'],rgcmd($f,'submit',$answer));rgassert($f['state']==='COMPLETED');$final=json_decode($owner->store->find('executions',$f['execution_id'])['final_json'],true);rgassert($final['answers']===$answer&&$final['rows'][0]['value']===$answer['R_REG']);});
function rgstudy($long,$d){global $owner;$v=$owner->publish($d['id'],1);$definition=pe_native_transport_fixture(pe_definition());if($long)$definition=L\Configuration::apply($definition,array('initial_screen'=>array_replace_recursive(L\InitialScreen::defaults(),array('authentication'=>array('verification'=>'NEVER')))));foreach($definition['nodes'] as &$n)if(isset($n['metadata']['native_version_id'])){$n['metadata']['native_version_id']=$v['version_id'];$n['metadata']['native_definition_hash']=$v['definition_hash'];$n['metadata']['native_questions']=array(array('id'=>'EL_REG','response_key'=>'R_REG','variable_name'=>'text_1','label'=>'Registration','value_type'=>'BOOLEAN','options'=>array(),'page'=>0,'randomization_id'=>null,'randomization_path'=>array(),'registration'=>true));}unset($n);foreach($definition['nodes'] as &$n)if($n['kind']==='QUESTION')$n=array_intersect_key($n,array_flip(array('id','version_id','parent_id','position','content')))+array('kind'=>'CONTENT','type'=>'TEXT','durable_reference'=>null);unset($n);return pe_publish('simple',false,$definition);}
rgtest('longitudinal source is own authentication email and response edits never change it',function()use($owner,$d){$p=rgstudy(true,$d);$f=pf_enroll($p);$cookie=L\Identity::cookieName($p['public']);$_COOKIE[$cookie]=$f['token'];try{$a=EIPSI\StudyEngine\Runtime\NativeBridge::offer($f);$frame=$owner->view($a['execution_id']);$person=pf_participant($f);$savedToken=$_COOKIE[$cookie];$_COOKIE[$cookie]='invalid';$denied=false;try{$owner->view($a['execution_id']);}catch(Throwable $e){$denied=$e->getCode()===403;}$_COOKIE[$cookie]=$savedToken;rgassert($denied);rgassert($frame['registration_source']===$person['email']);$frame=$owner->command($frame['execution_id'],rgcmd($frame,'open'));$value=array('register'=>true,'value'=>'different@example.test');$frame=$owner->command($frame['execution_id'],rgcmd($frame,'submit',array('R_REG'=>$value)));rgassert(pf_participant($f)['email']===$person['email']);$row=$owner->store->find('executions',$frame['execution_id']);$stored=$row['final_json'];pf_db()->transactional(function()use($person){pf_db()->update('participants',array('email'=>null),pf_db()->prepare('id=%s',$person['id']));});rgassert($owner->store->find('executions',$row['id'])['final_json']===$stored);rgassert(json_decode($stored,true)['answers']['R_REG']===$value);}finally{unset($_COOKIE[$cookie]);}});
rgtest('transversal source is nonsecret anonymous identity, never the access credential',function()use($owner,$d){$p=rgstudy(false,$d);$f=pe_runtime()->handle($p['public']);$class='EIPSI\\StudyEngine\\Runtime\\AnonymousAccess';$_COOKIE[$class::cookieName($p['public'])]=$f['token'];try{$a=EIPSI\StudyEngine\Runtime\NativeBridge::offer($f);$frame=$owner->view($a['execution_id']);rgassert($frame['registration_source']===$f['access']['id']);rgassert($frame['registration_source']!==$f['token']);$frame=$owner->command($frame['execution_id'],rgcmd($frame,'open'));$frame=$owner->command($frame['execution_id'],rgcmd($frame,'submit',array('R_REG'=>array('register'=>false,'value'=>null))));$final=json_decode($owner->store->find('executions',$frame['execution_id'])['final_json'],true);rgassert($final['answers']['R_REG']===array('register'=>false,'value'=>null));rgassert(strpos(json_encode($final['answers']),$f['access']['id'])===false);}finally{unset($_COOKIE[$class::cookieName($p['public'])]);}});
echo "$tests tests, $failures failures\n";exit($failures?1:0);
